    ws = wb[sh]
    print(f"\n=== {sh} dims={ws.dimensions} max_row={ws.max_row} max_col={ws.max_column}")
    # find the main data table and print a few rows
    for r in range(1, min(ws.max_row, 60)+1):
        vals = [ws.cell(r,c).value for c in range(1, min(ws.max_column,10)+1)]
        if any(v is not None for v in vals):
            s = " | ".join("" if v is None else str(v)[:28] for v in vals)
            if r>1: print(r, ":", s[:200])
EOF", "description": "Reopen workbook and inspect all tab contents"}

